const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:2}).format(Number(v)/100);
const date=v=>new Date(v).toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'});
const paths={search:'m21 21-5-5 M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0',cart:'M2 3h3l3 12h11l3-9H6 M9 21h.01 M19 21h.01',user:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2 M16 5a4 4 0 1 1-8 0 4 4 0 0 1 8 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',arrow:'M4 12h16 m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',menu:'M3 6h18 M3 12h18 M3 18h18',close:'m6 6 12 12 M6 18 18 6',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',truck:'M1 4h14v13H1z M15 9h4l4 4v4h-8 M8 18a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M22 18a3 3 0 1 1-6 0 3 3 0 0 1 6 0',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6z m-5 10 3 3 7-7',card:'M2 5h20v14H2z M2 9h20 M5 15h4',headphones:'M3 14v-3a9 9 0 0 1 18 0v3 M3 12h4v9H3z M17 12h4v9h-4z',cpu:'M6 6h12v12H6z M9 9h6v6H9z M9 2v4 M15 2v4 M9 18v4 M15 18v4 M2 9h4 M2 15h4 M18 9h4 M18 15h4',laptop:'M4 3h16v13H4z M1 20h22l-3-4H4z',monitor:'M2 3h20v14H2z M12 17v4 M7 21h10',mouse:'M5 10a7 7 0 0 1 14 0v5a7 7 0 0 1-14 0z M12 3v7 M5 10h14',drive:'M4 3h16v18H4z M17 10a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M12 10l5 7 M7 18h.01',droplet:'M12 2S4 10 4 15a8 8 0 0 0 16 0c0-5-8-13-8-13z',camera:'M2 7h4l2-4h8l2 4h4v14H2z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',printer:'M6 9V2h12v7 M6 18H2V9h20v9h-4 M6 14h12v8H6z M18 12h.01',code:'m8 5-7 7 7 7 M16 5l7 7-7 7 M14 2l-4 20',phone:'M6 2h12v20H6z M10 18h4',wifi:'M2 8a16 16 0 0 1 20 0 M5 12a11 11 0 0 1 14 0 M8 16a6 6 0 0 1 8 0 M12 20h.01',zap:'m13 2-9 12h7l-1 8L21 9h-8z',bag:'M3 7h18l-1 15H4z M8 7V5a4 4 0 0 1 8 0v2',box:'m3 6 9-4 9 4v12l-9 4-9-4z M3 6l9 5 9-5 M12 11v11 M7 4l10 5',game:'M7 7h10c4 0 6 9 4 12s-5-2-6-3H9c-1 1-4 6-6 3S3 7 7 7z M7 10v5 M4.5 12.5h5 M16 11h.01 M19 14h.01',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 16h12l1-16 M10 10v7 M14 10v7',check:'m4 12 5 5L21 5',logout:'M10 3H3v18h7 M9 12h13 m-5-5 5 5-5 5',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M9 2h6l1 4 4 1 2 5-3 3-1 5-5 2-3-3-5-1-2-5 3-3 1-5z',mail:'M2 4h20v16H2z m0 0 10 9L22 4',edit:'m15 4 5 5 M3 21l5-1L22 6l-4-4L4 16z',plus:'M12 4v16 M4 12h16'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.box}"/></svg>`;
const state={user:null,csrf:'',settings:{},categories:[],cart:[],favorites:[],routeId:0};
const statusLabels={pending:'Pendiente de pago',paid:'Pago confirmado',processing:'En preparación',shipped:'Enviado',delivered:'Entregado',cancelled:'Cancelado',review:'En revisión'};
const statusBadge=s=>`<span class="status ${esc(s)}">${esc(statusLabels[s]||s)}</span>`;
const qs=o=>new URLSearchParams(Object.entries(o).filter(([,v])=>v!==undefined&&v!==null&&v!=='')).toString();
const catName=s=>state.categories.find(c=>c.slug===s)?.name||s;
const categoryLink=(slug,label)=>`<a href="#catalogo?category=${encodeURIComponent(slug)}">${label||esc(catName(slug))}</a>`;
async function api(action,data=null,params={}){const opts={credentials:'same-origin',headers:{}};if(data!==null){opts.method='POST';opts.headers['X-CSRF-Token']=state.csrf;if(data instanceof FormData)opts.body=data;else{opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data)}}const r=await fetch('/api.php?'+qs({action,...params}),opts);let result;try{result=await r.json()}catch{throw new Error('No se pudo conectar con la tienda. Intenta de nuevo.')}if(!r.ok)throw new Error(result.error||'No se pudo completar la operación.');return result}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),4000)}
function photo(p,extra=''){return p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy" decoding="async" ${extra}>`:`<span class="photo-missing">${icon(state.categories.find(c=>c.slug===p.category)?.icon||'box')}<span>Imagen por confirmar</span></span>`}
function card(p){const off=p.compare_price>p.price?Math.round(100-p.price/p.compare_price*100):0;return `<article class="product-card">${off?`<span class="badge">-${off}%</span>`:''}<button class="favorite icon-button ${state.favorites.includes(p.id)?'saved':''}" data-favorite="${p.id}" aria-label="Guardar ${esc(p.name)} en favoritos">${icon('heart')}</button><a href="#producto?id=${p.id}" class="product-photo">${photo(p)}</a><div class="product-info"><span class="brand-label">${esc(p.brand)}</span><a href="#producto?id=${p.id}"><h3>${esc(p.name)}</h3></a><p class="spec-line">${esc(p.description)}</p><span class="availability ${p.stock?'':'out'}">${p.stock?`${p.stock} disponibles${state.settings.demo_mode?' · demo':''}`:'Sin existencias'}</span><div class="price-row">${off?`<span class="old-price">${money(p.compare_price)}</span>`:''}<span class="price">${money(p.price)}</span></div><button class="button" data-add="${p.id}" ${!p.stock?'disabled':''}>${p.stock?'Agregar al carrito':'Agotado'}</button></div></article>`}
function logo(){return `<a href="#inicio" class="brand" aria-label="NexTech inicio"><span class="brand-symbol">N</span><span><span class="brand-name">NEXTECH</span><span class="brand-tag">TU MUNDO GAMER</span></span></a>`}
function header(){return `${state.settings.demo_mode?'<div class="demo-bar">TIENDA EN DEMOSTRACIÓN · Precios e inventario de prueba · No se realizan cobros</div>':''}<header><div class="topline"><div class="wrap header-main">${logo()}<form class="header-search" id="search-form" role="search"><input name="q" placeholder="¿Qué estás buscando?" aria-label="Buscar productos" maxlength="100" autocomplete="off"><button type="submit" aria-label="Buscar">${icon('search')}</button></form><div class="header-actions"><a class="header-action location" href="#ayuda">${icon('pin')}<span><small>Enviamos a</small>México</span></a><a class="header-action" href="#cuenta">${icon('user')}<span class="action-text"><small>${state.user?'Hola, '+esc(state.user.name.split(' ')[0]):'Iniciar sesión'}</small>Mi cuenta</span></a><a class="cart-link" href="#carrito" aria-label="Ver carrito">${icon('cart')}<span class="cart-count">${state.cart.reduce((a,p)=>a+Number(p.qty),0)}</span></a></div></div></div><nav class="nav" aria-label="Navegación principal"><div class="wrap nav-inner"><button class="nav-menu-button" id="category-toggle" aria-expanded="false" aria-controls="category-menu">${icon('menu')}Categorías ${icon('down')}</button><a href="#catalogo?category=computadoras">PC Gaming</a><a href="#catalogo?category=computadoras&q=laptop">Laptops</a><a href="#catalogo?category=componentes">Componentes</a><a href="#catalogo?category=accesorios">Periféricos</a><a href="#catalogo?category=almacenamiento">Almacenamiento</a><a href="#catalogo?category=redes">Redes</a><a href="#catalogo?category=audio">Audio y Streaming</a><a href="#catalogo?category=software">Software</a><a href="#catalogo?offers=1" class="accent">Ofertas</a><a class="gamer" href="#catalogo?featured=1">${icon('game')}Zona Gamer</a><div class="category-menu" id="category-menu" hidden>${state.categories.map(c=>`<a href="#catalogo?category=${c.slug}">${icon(c.icon)}${esc(c.name)}<span class="chev">›</span></a>`).join('')}</div></div></nav></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-grid"><div class="footer-brand">${logo()}<p>Todo para tu próximo nivel.<br>Computadoras, componentes y tecnología.</p><div class="payments"><span>Visa</span><span>Mastercard</span><span>Mercado Pago</span><span>Transferencia</span></div></div><div><h3>EXPLORA NEXTECH</h3><div class="footer-links">${categoryLink('computadoras')}${categoryLink('componentes')}${categoryLink('accesorios','Periféricos')}${categoryLink('almacenamiento')}<a href="#catalogo">Todo el catálogo</a></div></div><div><h3>ESTAMOS PARA AYUDARTE</h3><div class="footer-links"><a href="#ayuda">Envíos y pagos</a><a href="#cuenta?tab=pedidos">Mis pedidos</a><a href="#devoluciones">Cambios y garantías</a><a href="#privacidad">Aviso de privacidad</a><a href="#terminos">Términos y condiciones</a></div></div><div><h3>ATENCIÓN A CLIENTES</h3><p>Consulta tus pedidos desde tu cuenta.</p>${state.settings.support_email?`<a href="mailto:${esc(state.settings.support_email)}">${esc(state.settings.support_email)}</a>`:'<a href="#ayuda">Información de contacto</a>'}${state.settings.support_phone?`<p>${esc(state.settings.support_phone)}</p>`:''}${state.user?.role==='admin'?'<p><a class="accent" href="#admin">Administrar tienda →</a></p>':''}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} NexTech. Todos los derechos reservados.</span><span>Precios en MXN · Las marcas pertenecen a sus respectivos titulares.</span></div></div></footer>`}
function shell(content){$('#app').innerHTML=header()+`<main id="main" tabindex="-1">${content}</main>`+footer();imageFallbacks()}
function imageFallbacks(){$$('img').forEach(im=>im.addEventListener('error',()=>{im.replaceWith(Object.assign(document.createElement('span'),{className:'photo-missing',textContent:'Imagen no disponible'}))},{once:true}))}
const loading=()=>'<div class="loading"><span class="spinner"></span><p>Cargando…</p></div>';
const empty=(title,message,href='#catalogo',cta='Explorar productos',type='box')=>`<div class="empty">${icon(type)}<h2>${esc(title)}</h2><p>${esc(message)}</p><a class="button" href="${href}">${esc(cta)}</a></div>`;
function breadcrumb(label){return `<div class="breadcrumb"><a href="#inicio">Inicio</a><span>›</span><span>${esc(label)}</span></div>`}
async function home(){const [{items},laptops,keyboards]=await Promise.all([api('products',null,{featured:1,limit:16}),api('products',null,{category:'computadoras',q:'laptop',limit:1}),api('products',null,{category:'accesorios',q:'teclado',limit:1})]);const laptop=laptops.items[0];const find=c=>items.find(p=>p.category===c);const selected=[find('computadoras'),laptop,find('componentes'),find('monitores'),keyboards.items[0],find('audio'),find('almacenamiento'),find('redes')].filter(Boolean);const tiles=[['computadoras','PC Gaming'],['computadoras','Laptops'],['componentes','Componentes'],['accesorios','Periféricos'],['almacenamiento','Almacenamiento'],['monitores','Monitores'],['redes','Redes'],['audio','Audio y Streaming'],['celulares','Celulares'],['apple','Apple']];return `<section class="hero"><div class="wrap hero-inner"><div class="hero-copy"><div class="eyebrow">BIENVENIDO A TU SIGUIENTE NIVEL</div><h1>Equipa<br>tu <span>realidad</span></h1><p>PCs | Laptops | Componentes | Periféricos<br>Y todo el ecosistema gamer</p><a class="button cyan" href="#catalogo">VER PRODUCTOS ${icon('arrow')}</a></div></div><div class="hero-note">Más que tecnología,<br>es tu mundo.</div></section><section class="benefits" aria-label="Servicios de la tienda"><div class="wrap benefits-inner">${[['truck','Envíos a México','Hasta la puerta de tu casa'],['shield','Compra con confianza','Consulta todos tus pedidos'],['card','Distintas formas de pago','Elige al finalizar tu compra'],['headphones','Soporte para tu setup','Estamos para ayudarte'],['zap','Tu siguiente nivel','Tecnología para cada reto']].map(b=>`<div class="benefit">${icon(b[0])}<div><strong>${b[1]}</strong><span>${b[2]}</span></div></div>`).join('')}</div></section><div class="wrap home-content"><div class="category-strip">${tiles.map(([c,label],i)=>`<a class="category-tile" href="#catalogo?category=${c}${i===1?'&q=laptop':''}">${i===1&&laptop?photo(laptop):find(c)?photo(find(c)):icon(state.categories.find(x=>x.slug===c)?.icon)}<span>${label}</span></a>`).join('')}</div><div class="promo-grid">${[['computadoras','Laptops gamer','Rendimiento<br>sin límites','Ver laptops'],['componentes','Componentes','Potencia<br>tu setup','Ver componentes'],['accesorios','Periféricos','Juega<br>a otro nivel','Ver periféricos']].map(([c,k,t,cta])=>`<a class="promo" href="#catalogo?category=${c}${c==='computadoras'?'&q=laptop':''}">${c==='computadoras'&&laptop?photo(laptop):c==='accesorios'&&keyboards.items[0]?photo(keyboards.items[0]):find(c)?photo(find(c)):''}<div class="eyebrow">${k}</div><h2>${t}</h2><span class="button">${cta} →</span></a>`).join('')}</div><section><div class="section-head"><h2>Productos destacados</h2><a href="#catalogo">Ver todos ${icon('arrow')}</a></div><div class="product-grid featured">${selected.map(card).join('')}</div></section><div class="brand-strip" aria-label="Marcas del catálogo">${['ASUS','HyperX','AMD','intel.','Kingston','SAMSUNG','TP-Link','Apple','RAZER'].map(x=>`<span>${x}</span>`).join('')}</div><section class="end-banner"><div><span class="eyebrow">DALE VIDA A TU SETUP</span><h2>Cada pieza cuenta. Encuentra la tuya.</h2><p>Explora nuestras ${state.categories.length} categorías de tecnología.</p></div><a class="button secondary" href="#catalogo">Explorar catálogo ${icon('arrow')}</a></section></div>`}
async function catalog(params){const filters=Object.fromEntries(params);const data=await api('products',null,{...filters,limit:24});const name=filters.category==='computadoras'&&filters.q==='laptop'?'Laptops':filters.q?`Resultados para “${filters.q}”`:filters.category?catName(filters.category):filters.offers?'Ofertas':filters.featured?'Zona Gamer':'Todo el catálogo';const filterLink=changes=>'#catalogo?'+qs({...filters,page:1,...changes});return `<div class="wrap page">${breadcrumb(name)}<div class="page-title"><span class="eyebrow">ENCUENTRA TU SIGUIENTE UPGRADE</span><h1>${esc(name)}</h1></div><div class="catalog-layout"><aside class="sidebar"><h3>Categorías</h3><a href="#catalogo" class="${!filters.category?'active':''}">${icon('box')}Todos los productos</a>${state.categories.map(c=>`<a href="${filterLink({category:c.slug,q:'',brand:'',featured:'',offers:''})}" class="${filters.category===c.slug?'active':''}">${icon(c.icon)}${esc(c.name)}</a>`).join('')}<hr><label>Marca<select id="brand-filter"><option value="">Todas las marcas</option>${data.brands.map(b=>`<option ${filters.brand===b?'selected':''} value="${esc(b)}">${esc(b)}</option>`).join('')}</select></label><label class="check-label"><input type="checkbox" id="stock-filter" ${filters.stock?'checked':''}> Solo productos en stock</label></aside><section><div class="catalog-toolbar"><p><strong>${data.total}</strong> productos encontrados</p><label class="sr-sort"><select id="sort-filter" aria-label="Ordenar productos">${[['','Destacados primero'],['price-asc','Precio: menor a mayor'],['price-desc','Precio: mayor a menor'],['name','Nombre: A a Z'],['newest','Más recientes']].map(([v,t])=>`<option value="${v}" ${(filters.sort||'')===v?'selected':''}>${t}</option>`).join('')}</select></label></div>${data.items.length?`<div class="product-grid">${data.items.map(card).join('')}</div>`:empty('No encontramos productos','Prueba con otra palabra o elimina los filtros.')}<div class="pagination">${Array.from({length:data.pages},(_,i)=>i+1).filter(p=>Math.abs(p-data.page)<=2||p===1||p===data.pages).map(p=>`<a class="${p===data.page?'active':''}" href="#catalogo?${qs({...filters,page:p})}" aria-label="Página ${p}">${p}</a>`).join('')}</div></section></div></div>`}
async function productPage(params){const p=await api('product',null,{id:params.get('id')});const related=await api('products',null,{category:p.category,limit:5});return `<div class="wrap page">${breadcrumb(catName(p.category)+' / '+p.name)}<div class="product-detail"><div class="detail-photo">${photo(p)}</div><section class="detail-info"><span class="eyebrow">${esc(p.brand)}</span><h1>${esc(p.name)}</h1><p>${esc(p.description)}</p><div class="tiny muted">SKU: ${esc(p.sku)}</div><hr><div class="price-row"><span class="price">${money(p.price)}</span>${p.compare_price>p.price?`<span class="old-price">${money(p.compare_price)}</span>`:''}</div><p class="tiny muted">Pesos mexicanos${state.settings.demo_mode?' · Precio de demostración':''}</p><div class="availability ${p.stock?'':'out'}">${p.stock?`${p.stock} unidades disponibles${state.settings.demo_mode?' en demostración':''}`:'Actualmente sin existencias'}</div><div class="detail-buy"><input id="product-qty" type="number" min="1" max="${Math.min(99,p.stock)||1}" value="1" aria-label="Cantidad"><button class="button" data-add="${p.id}" data-detail="1" ${!p.stock?'disabled':''}>${icon('cart')}Agregar al carrito</button><button class="icon-button" data-favorite="${p.id}" aria-label="Guardar en favoritos">${icon('heart')}</button></div><div class="detail-meta"><span class="flex">${icon('truck')}Envío a México</span><a class="flex" href="#devoluciones">${icon('shield')}Garantías y devoluciones</a></div></section></div><div class="spec-grid"><section class="panel"><h2>Especificaciones</h2><dl class="spec-table">${Object.entries(p.specs).map(([k,v])=>`<div><dt>${esc(k.replaceAll('_',' '))}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></section><section class="panel"><h2>Sobre este producto</h2><p>${esc(p.description)}</p>${p.source_url?`<a class="accent" href="${esc(p.source_url)}" target="_blank" rel="noopener noreferrer">Consultar información del fabricante ↗</a><p class="tiny muted">Referencia consultada: ${esc(p.source_checked||'ver fuente')}. Verifica el modelo y la compatibilidad antes de comprar.</p>`:''}</section></div><div class="section-head"><h2>También te puede interesar</h2></div><div class="product-grid">${related.items.filter(x=>x.id!==p.id).slice(0,4).map(card).join('')}</div></div>`}
function guestCart(){try{return JSON.parse(localStorage.getItem('nextech_cart')||'[]').filter(p=>Number.isInteger(p.id)&&p.qty>0).slice(0,50)}catch{return []}}
async function loadCart(){if(state.user)state.cart=await api('cart');else{const local=guestCart();const result=await Promise.allSettled(local.map(async p=>({...await api('product',null,{id:p.id}),qty:p.qty})));state.cart=result.filter(r=>r.status==='fulfilled').map(r=>r.value)}}
function updateBadge(){const b=$('.cart-count');if(b)b.textContent=state.cart.reduce((a,p)=>a+Number(p.qty),0)}
async function setCart(id,qty){qty=Math.max(0,Math.min(99,Number(qty)));if(state.user)await api('cart',{product_id:id,qty});else{let rows=guestCart().filter(p=>p.id!==id);if(qty){const p=await api('product',null,{id});if(qty>p.stock)throw Error('No hay suficientes unidades disponibles.');rows.push({id,qty})}localStorage.setItem('nextech_cart',JSON.stringify(rows))}await loadCart();updateBadge()}
async function mergeCart(){const local=guestCart();await loadCart();for(const p of local){const current=state.cart.find(x=>x.id===p.id);try{await api('cart',{product_id:p.id,qty:Math.min(99,p.qty+Number(current?.qty||0))})}catch{toast('Un producto de tu carrito cambió de disponibilidad.')}}localStorage.removeItem('nextech_cart');await loadCart()}
function totals(){const subtotal=state.cart.reduce((sum,p)=>sum+p.price*p.qty,0);const shipping=subtotal>=state.settings.free_shipping?0:state.settings.shipping_price;return {subtotal,shipping,total:subtotal+shipping}}
function summary(checkout=false){const t=totals();return `<aside class="panel summary"><h2>Resumen de tu compra</h2>${checkout?`<div class="checkout-items">${state.cart.map(p=>`<div><span>${p.qty} × ${esc(p.name)}</span><strong>${money(p.price*p.qty)}</strong></div>`).join('')}</div>`:''}<div class="line"><span>Productos</span><span>${money(t.subtotal)}</span></div><div class="line"><span>Envío</span><span>${t.shipping?money(t.shipping):'Gratis'}</span></div><div class="line total"><span>Total</span><span>${money(t.total)}</span></div><p class="tiny muted">${state.settings.demo_mode?'Demostración sin cobro real.':'Total en MXN. Impuestos incluidos en los precios configurados por la tienda.'}</p>${!checkout?'<a class="button" href="#checkout">Continuar con mi compra →</a>':''}<p class="tiny muted">Envío gratis desde ${money(state.settings.free_shipping)}.</p></aside>`}
async function cartPage(){await loadCart();return `<div class="wrap page">${breadcrumb('Mi carrito')}<div class="page-title"><h1>Tu carrito</h1><p>Cada pieza, un paso más cerca de tu setup.</p></div>${state.cart.length?`<div class="cart-layout"><section class="panel">${state.cart.map(p=>`<div class="cart-item"><a href="#producto?id=${p.id}">${photo(p)}</a><div><a href="#producto?id=${p.id}"><h3>${esc(p.name)}</h3></a><span class="tiny muted">${money(p.price)} por unidad</span><div class="tiny ${p.stock<p.qty?'accent':'muted'}">${p.stock<p.qty?'Existencias insuficientes':`${p.stock} disponibles`}</div></div><input type="number" value="${p.qty}" min="1" max="99" data-cart-qty="${p.id}" aria-label="Cantidad de ${esc(p.name)}"><span class="price">${money(p.price*p.qty)}</span><button class="icon-button" data-remove="${p.id}" aria-label="Quitar ${esc(p.name)}">${icon('trash')}</button></div>`).join('')}<p class="tiny muted" style="margin-top:20px">Los precios y las existencias se vuelven a comprobar al crear el pedido.</p><a class="accent" href="#catalogo">← Seguir comprando</a></section>${summary()}</div>`:empty('Tu carrito está esperando','Encuentra las piezas para tu próximo proyecto.','#catalogo','Explorar productos','cart')}</div>`}
function routeParams(){const [path,query='']=location.hash.slice(1).split('?');return {path:path||'inicio',params:new URLSearchParams(query)}}
async function route(){const id=++state.routeId;const {path,params}=routeParams();shell(loading());try{let content;if(path==='inicio')content=await home();else if(path==='catalogo')content=await catalog(params);else if(path==='producto')content=await productPage(params);else if(path==='carrito')content=await cartPage();else content=await otherPage(path,params);if(id!==state.routeId)return;shell(content);window.scrollTo(0,0);document.title=(path==='inicio'?'NexTech | Tu mundo gamer':`${({catalogo:'Catálogo',producto:'Producto',carrito:'Mi carrito',cuenta:'Mi cuenta',checkout:'Finalizar compra',admin:'Administración',pedido:'Mi pedido'})[path]||'NexTech'} | NexTech`)}catch(e){if(id===state.routeId)shell(`<div class="wrap page"><div class="notice error" role="alert">${esc(e.message)}</div><p><a class="button secondary" href="#inicio">Volver al inicio</a></p></div>`)}}
function modal(title,body){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-close-modal aria-label="Cerrar">${icon('close')}</button></div>${body}`;d.showModal();imageFallbacks()}
function formError(form,error){let el=$('.form-error',form);if(!el){el=document.createElement('p');el.className='notice error form-error';el.setAttribute('role','alert');form.prepend(el)}el.textContent=error.message;el.scrollIntoView({block:'nearest'})}
async function busy(form,fn){const b=$('button[type=submit]',form);if(b)b.disabled=true;$('.form-error',form)?.remove();try{await fn()}catch(e){formError(form,e)}finally{if(b)b.disabled=false}}
document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main')?.focus();$('#main')?.scrollIntoView();return}const close=e.target.closest('[data-close-modal]');if(close){$('#modal').close();return}const toggle=e.target.closest('#category-toggle');if(toggle){const m=$('#category-menu');m.hidden=!m.hidden;toggle.setAttribute('aria-expanded',String(!m.hidden));return}if(!e.target.closest('.category-menu')){const m=$('#category-menu');if(m){m.hidden=true;$('#category-toggle')?.setAttribute('aria-expanded','false')}}const add=e.target.closest('[data-add]');if(add){add.disabled=true;try{const id=Number(add.dataset.add);const qty=add.dataset.detail?Number($('#product-qty').value):1;const old=Number(state.cart.find(p=>p.id===id)?.qty||0);await setCart(id,old+qty);toast('Producto agregado a tu carrito')}catch(error){toast(error.message)}finally{add.disabled=false}return}const remove=e.target.closest('[data-remove]');if(remove){try{await setCart(Number(remove.dataset.remove),0);await route()}catch(error){toast(error.message)}return}const favorite=e.target.closest('[data-favorite]');if(favorite){if(!state.user){location.hash='cuenta';toast('Inicia sesión para guardar tus favoritos.');return}try{const id=Number(favorite.dataset.favorite);const r=await api('favorite',{id});state.favorites=r.saved?[...state.favorites,id]:state.favorites.filter(x=>x!==id);favorite.classList.toggle('saved',r.saved);toast(r.saved?'Guardado en tus favoritos':'Eliminado de favoritos')}catch(error){toast(error.message)}return}await extraClick(e)});
document.addEventListener('change',async e=>{if(['sort-filter','brand-filter','stock-filter'].includes(e.target.id)){const {params}=routeParams();const key={'sort-filter':'sort','brand-filter':'brand','stock-filter':'stock'}[e.target.id];const value=e.target.id==='stock-filter'?(e.target.checked?'1':''):e.target.value;if(value)params.set(key,value);else params.delete(key);params.delete('page');location.hash='catalogo?'+params;return}if(e.target.dataset.cartQty){try{await setCart(Number(e.target.dataset.cartQty),Number(e.target.value));await route()}catch(error){toast(error.message);await route()}}await extraChange(e)});
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='search-form'){const value=new FormData(e.target).get('q').trim();location.hash='catalogo?'+qs({q:value});return}await extraSubmit(e)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#category-menu')?.setAttribute('hidden','');$('#category-toggle')?.setAttribute('aria-expanded','false')}});
window.addEventListener('hashchange',route);
async function bootstrap(){try{Object.assign(state,await api('bootstrap'));await loadCart();if(state.user)state.favorites=(await api('favorites')).map(p=>p.id);await route()}catch(e){shell(`<div class="wrap page"><div class="panel"><h1>NexTech</h1><p>${esc(e.message)}</p><a class="button" href="/install.php">Abrir instalador</a></div></div>`)}}
// Pantallas de cliente y administración: mismo servidor, sesión y catálogo.
function authForm(mode='login'){return `<div class="wrap page"><div class="panel auth-panel"><span class="eyebrow">BIENVENIDO A NEXTECH</span><h1>${mode==='register'?'Crea tu cuenta':'Tu mundo, en un lugar.'}</h1><div class="auth-tabs"><button data-auth-mode="login" class="${mode==='login'?'active':''}">Iniciar sesión</button><button data-auth-mode="register" class="${mode==='register'?'active':''}">Crear cuenta</button></div><form id="auth-form" data-mode="${mode}" class="stack">${mode==='register'?'<label>Nombre completo<input name="name" required minlength="2" maxlength="120" autocomplete="name"></label>':''}<label>Correo electrónico<input name="email" type="email" required maxlength="190" autocomplete="email"></label><label>Contraseña<input name="password" type="password" required minlength="${mode==='register'?10:1}" maxlength="128" autocomplete="${mode==='register'?'new-password':'current-password'}"></label>${mode==='register'?'<p class="tiny muted">Usa al menos 10 caracteres.</p><label class="check-label"><input name="accept" type="checkbox" required> <span>Acepto los <a class="accent" href="#terminos" target="_blank">términos y condiciones</a> y el <a class="accent" href="#privacidad" target="_blank">aviso de privacidad</a>.</span></label>':''}<button class="button" type="submit">${mode==='register'?'Crear mi cuenta':'Iniciar sesión'}</button>${mode==='login'?'<button class="link-button" type="button" data-forgot>Olvidé mi contraseña</button>':''}</form></div></div>`}
function accountNav(tab){return `<aside class="panel account-nav"><p>Hola, <strong>${esc(state.user.name.split(' ')[0])}</strong></p>${[['perfil','user','Mi perfil'],['pedidos','box','Mis pedidos'],['direcciones','pin','Mis direcciones'],['favoritos','heart','Mis favoritos']].map(([v,i,t])=>`<a class="${tab===v?'active':''}" href="#cuenta?tab=${v}">${icon(i)}${t}</a>`).join('')}${state.user.role==='admin'?`<a href="#admin">${icon('settings')}Administración</a>`:''}<a href="#" data-logout>${icon('logout')}Cerrar sesión</a></aside>`}
function addressForm(a={}){return `<form id="address-form" class="form-grid"><input type="hidden" name="id" value="${a.id||0}"><label class="full">Nombre de la dirección<input name="label" value="${esc(a.label||'Casa')}" required maxlength="50"></label>${addressInputs(a)}<button class="button full" type="submit">Guardar dirección</button></form>`}
function addressInputs(a={}){return `${[['recipient','Nombre de quien recibe',120,'name'],['phone','Teléfono',30,'tel'],['street','Calle y número exterior / interior',250,'street-address'],['colony','Colonia',120,'address-line2'],['city','Municipio o alcaldía',120,'address-level2'],['state','Estado',120,'address-level1'],['postal_code','Código postal',5,'postal-code']].map(([n,l,max,ac])=>`<label class="${n==='street'?'full':''}">${l}<input name="${n}" value="${esc(a[n]||'')}" required maxlength="${max}" autocomplete="${ac}" ${n==='postal_code'?'pattern="[0-9]{5}" inputmode="numeric"':n==='phone'?'type="tel" minlength="10"':'minlength="2"'}></label>`).join('')}<label>País<input value="México" disabled aria-label="País México"></label><label class="full">Indicaciones de entrega (opcional)<textarea name="notes" maxlength="500">${esc(a.notes||'')}</textarea></label>`}
async function accountPage(params){if(!state.user)return authForm(params.get('mode')||'login');const tab=params.get('tab')||'perfil';let body='';if(tab==='perfil'){body=`<div class="page-title"><h1>Mi perfil</h1><p>Tu información y la seguridad de tu cuenta.</p></div><section class="panel"><form id="profile-form" class="form-grid"><label>Nombre completo<input name="name" value="${esc(state.user.name)}" minlength="2" maxlength="120" required autocomplete="name"></label><label>Teléfono<input name="phone" type="tel" value="${esc(state.user.phone)}" maxlength="30" autocomplete="tel"></label><label class="full">Correo electrónico<input value="${esc(state.user.email)}" disabled></label><button class="button" type="submit">Guardar cambios</button></form></section><section class="panel" style="margin-top:22px"><h2>Cambiar contraseña</h2><form id="password-form" class="form-grid"><label>Contraseña actual<input name="current_password" type="password" required autocomplete="current-password"></label><label>Nueva contraseña<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><button class="button" type="submit">Actualizar contraseña</button></form></section>`}else if(tab==='pedidos'){const orders=await api('orders');body=`<div class="page-title"><h1>Mis pedidos</h1><p>El recorrido de cada compra, de principio a fin.</p></div>${orders.length?orders.map(o=>`<article class="order-card"><div class="between"><div><h3>${esc(o.id)}</h3><span class="tiny muted">${date(o.created_at)}</span></div>${statusBadge(o.status)}</div><div class="between" style="margin-top:20px"><span>${o.items.reduce((n,p)=>n+Number(p.qty),0)} artículos · <strong>${money(o.total)}</strong>${o.provider==='demo'?' · Demostración':''}</span><a class="button secondary" href="#pedido?id=${o.id}">Ver pedido →</a></div></article>`).join(''):empty('Aún no tienes pedidos','Tus compras aparecerán aquí después de finalizar tu primer pedido.')}`}else if(tab==='direcciones'){const addresses=await api('addresses');state.addresses=addresses;body=`<div class="section-head"><h1>Mis direcciones</h1><button class="button" data-address="0">${icon('plus')}Agregar</button></div>${addresses.length?`<div class="address-grid">${addresses.map(a=>`<article class="panel address-card"><h3>${esc(a.label)}</h3><p>${esc(a.recipient)}<br>${esc(a.street)}<br>${esc(a.colony)}, ${esc(a.city)}<br>${esc(a.state)} · CP ${esc(a.postal_code)}<br>${esc(a.phone)}</p><div class="flex"><button class="button secondary" data-address="${a.id}">Editar</button><button class="icon-button" data-delete-address="${a.id}" aria-label="Eliminar ${esc(a.label)}">${icon('trash')}</button></div></article>`).join('')}</div>`:empty('Guarda tu primera dirección','Agrega una dirección para agilizar tus próximas compras.','#cuenta?tab=perfil','Volver a mi perfil','pin')}`}else{const products=await api('favorites');body=`<div class="page-title"><h1>Mis favoritos</h1><p>Las piezas que quieres tener cerca.</p></div>${products.length?`<div class="product-grid">${products.map(card).join('')}</div>`:empty('Tu próxima compra empieza aquí','Pulsa el corazón de un producto para guardarlo.','#catalogo','Explorar productos','heart')}`}return `<div class="wrap page">${breadcrumb('Mi cuenta')}<div class="account-layout">${accountNav(tab)}<section class="account-main">${body}</section></div></div>`}
async function checkoutPage(){if(!state.user){sessionStorage.setItem('nextech_return','checkout');return authForm()}await loadCart();if(!state.cart.length)return `<div class="wrap page">${empty('Tu carrito está vacío','Agrega un producto para continuar.','#catalogo','Ver catálogo','cart')}</div>`;const addresses=await api('addresses');state.addresses=addresses;state.checkoutKey??=crypto.randomUUID();const demo=state.settings.demo_mode;const methods=demo?[['demo','Pedido de demostración','Prueba el proceso sin realizar ningún cobro.']]:[['mercadopago','Mercado Pago','Tarjetas y otros métodos disponibles para tu cuenta.'],['stripe','Tarjeta con Stripe','Paga en la página segura de Stripe.'],['transfer','Transferencia bancaria','Recibirás los datos bancarios al crear el pedido.']].filter(([key])=>state.settings.payments[key]);return `<div class="wrap page">${breadcrumb('Finalizar compra')}<div class="page-title"><h1>Finaliza tu compra</h1><p>Ya casi es parte de tu setup.</p></div><div class="checkout-layout"><form id="checkout-form" class="stack"><section class="panel"><h2>1. Datos de entrega</h2>${addresses.length?`<label style="margin-bottom:20px">Usar una dirección guardada<select id="checkout-address"><option value="">Escribir otra dirección</option>${addresses.map(a=>`<option value="${a.id}">${esc(a.label)} · ${esc(a.street)}</option>`).join('')}</select></label>`:''}<div class="form-grid">${addressInputs({recipient:state.user.name,phone:state.user.phone})}</div></section><section class="panel stack"><h2>2. Forma de pago</h2>${methods.length?methods.map(([key,title,description],i)=>`<label class="payment-option"><input type="radio" name="provider" value="${key}" required ${i===0?'checked':''}><div><strong>${title}</strong><span>${description}</span></div>${icon(key==='demo'?'game':'card')}</label>`).join(''):'<p class="notice">La tienda está preparando sus formas de pago. Vuelve más tarde.</p>'}<p class="tiny muted">Los datos de tu tarjeta se capturan directamente en la pasarela. NexTech no almacena números de tarjeta.</p></section><section class="panel stack"><label class="check-label"><input type="checkbox" name="accept" required><span>He revisado mi pedido y acepto los <a class="accent" href="#terminos" target="_blank">términos y condiciones</a> y el <a class="accent" href="#privacidad" target="_blank">aviso de privacidad</a>.</span></label><button class="button" type="submit" ${!methods.length?'disabled':''}>${demo?'Crear pedido de demostración':'Confirmar pedido y continuar'} ${icon('arrow')}</button></section></form>${summary(true)}</div></div>`}
async function orderPage(params){if(!state.user)return authForm();const o=await api('order',null,{id:params.get('id')});const a=o.address;return `<div class="wrap page">${breadcrumb('Mi pedido')}<div class="between page-title"><div><span class="eyebrow">GRACIAS POR ELEGIR NEXTECH</span><h1>${esc(o.id)}</h1><p>Creado el ${date(o.created_at)}</p></div>${statusBadge(o.status)}</div>${o.provider==='demo'?'<p class="notice">Este es un pedido de demostración. No se realizó un cobro ni se programó un envío real.</p>':''}${o.status==='pending'?`<section class="panel" style="margin-bottom:24px"><h2>Tu pedido espera el pago</h2>${o.provider==='transfer'?`<p>Usa el número de pedido como referencia. La tienda confirmará el pago al verificar la transferencia.</p><p class="policy">${esc(o.bank_instructions)}</p>`:o.provider==='demo'?'<p>Puedes confirmar este pedido de prueba desde el panel de administración para recorrer los estados del envío.</p>':`<p>El pago se confirma cuando la pasarela lo notifica. Volver a esta página no confirma un cobro.</p>${o.checkout_url?`<a class="button" href="${esc(o.checkout_url)}">Ir a pagar ${icon('arrow')}</a>`:`<button class="button" data-retry-payment="${o.id}">Abrir pasarela de pago</button>`}`}<div class="flex" style="margin-top:15px"><button class="button secondary" data-refresh>Actualizar estado</button>${['demo','transfer'].includes(o.provider)?`<button class="link-button" data-cancel-order="${o.id}">Cancelar pedido</button>`:''}</div></section>`:''}<div class="cart-layout"><div class="stack"><section class="panel"><h2>Productos de tu pedido</h2>${o.items.map(p=>`<div class="cart-item"><a href="#producto?id=${p.product_id}">${photo(p)}</a><div><h3>${esc(p.name)}</h3><span class="tiny muted">${esc(p.sku)} · ${p.qty} unidades</span></div><span class="price">${money(p.price*p.qty)}</span></div>`).join('')}</section><section class="panel"><h2>Seguimiento</h2><ul class="timeline">${o.events.map(e=>`<li>${esc(e.message)}<small>${date(e.created_at)}</small></li>`).join('')}</ul></section></div><aside class="stack"><section class="panel summary"><h2>Resumen</h2><div class="line"><span>Productos</span><strong>${money(o.subtotal)}</strong></div><div class="line"><span>Envío</span><strong>${money(o.shipping)}</strong></div><div class="line total"><span>Total</span><strong>${money(o.total)}</strong></div><p class="tiny">Método: ${esc(({demo:'Demostración',transfer:'Transferencia',stripe:'Stripe',mercadopago:'Mercado Pago'})[o.provider]||o.provider)}</p></section><section class="panel"><h2>Dirección de entrega</h2><p>${esc(a.recipient)}<br>${esc(a.street)}<br>${esc(a.colony)}, ${esc(a.city)}<br>${esc(a.state)} · ${esc(a.postal_code)}<br>${esc(a.phone)}</p>${a.notes?`<p class="tiny muted">${esc(a.notes)}</p>`:''}${o.tracking?`<strong>Paquetería y guía</strong><p>${esc(o.tracking)}</p>`:''}</section></aside></div><p style="margin-top:28px"><a class="accent" href="#cuenta?tab=pedidos">← Volver a mis pedidos</a></p></div>`}
function policyPage(path){const labels={privacidad:'Aviso de privacidad',terminos:'Términos y condiciones',devoluciones:'Cambios, devoluciones y garantías'};const keys={privacidad:'privacy_text',terminos:'terms_text',devoluciones:'returns_text'};return `<div class="wrap page">${breadcrumb(labels[path])}<h1>${labels[path]}</h1><section class="panel policy">${esc(state.settings[keys[path]]||'La tienda está en preparación. Las condiciones comerciales y los datos del responsable se publicarán antes de activar las ventas. Actualmente no se aceptan pagos reales.')}</section></div>`}
function helpPage(){return `<div class="wrap page">${breadcrumb('Ayuda')}<div class="page-title"><h1>Estamos para ayudarte</h1><p>Información para comprar en NexTech.</p></div><div class="spec-grid"><section class="panel"><h2>Envíos dentro de México</h2><p>El envío tiene una tarifa de ${money(state.settings.shipping_price)}. Es gratis en pedidos desde ${money(state.settings.free_shipping)}.</p><p>El número de guía aparecerá en el detalle del pedido cuando la tienda despache tus productos. Los tiempos de entrega dependen de la paquetería y el destino.</p><a class="accent" href="#cuenta?tab=pedidos">Consultar mis pedidos →</a></section><section class="panel"><h2>Pagos</h2><p>Los métodos habilitados se muestran al finalizar la compra. El pago por tarjeta se realiza en la plataforma de pago correspondiente. Las transferencias se confirman después de su revisión.</p>${state.settings.demo_mode?'<p class="notice">La tienda está en demostración y no procesa cobros reales.</p>':''}</section><section class="panel"><h2>Contacto</h2>${state.settings.support_email?`<p><a class="accent" href="mailto:${esc(state.settings.support_email)}">${esc(state.settings.support_email)}</a></p>`:'<p>El canal de atención se publicará antes de activar las ventas.</p>'}${state.settings.support_phone?`<p>${esc(state.settings.support_phone)}</p>`:''}</section><section class="panel"><h2>Cambios y garantías</h2><p>Consulta las condiciones de la tienda y ten a mano el número de tu pedido al contactar a soporte.</p><a class="accent" href="#devoluciones">Consultar condiciones →</a></section></div></div>`}
async function adminPage(params){if(!state.user)return authForm();if(state.user.role!=='admin')throw Error('No tienes acceso a la administración.');const tab=params.get('tab')||'resumen';let body='';if(tab==='resumen'){const d=await api('admin-dashboard');body=`<div class="metrics">${[[d.products,'Productos'],[d.customers,'Clientes'],[d.orders,'Pedidos'],[money(d.revenue),'Ventas cobradas (sin demo)']].map(([v,l])=>`<div class="panel metric"><strong>${v}</strong><span>${l}</span></div>`).join('')}</div><div class="spec-grid"><section class="panel"><h2>Estado de la tienda</h2><p class="notice">${d.settings.demo_mode?'Demostración activa: no se reciben cobros reales.':'Ventas activas. Solo se venden los productos verificados.'}</p><div class="stack">${[['Mercado Pago',d.integrations.mercadopago],['Stripe',d.integrations.stripe],['Transferencias',d.integrations.transfer],['Correo de recuperación',d.email_enabled]].map(([t,v])=>`<div class="between"><span>${t}</span><span class="tiny ${v?'accent':'muted'}">${v?'Configurado':'Pendiente'}</span></div>`).join('')}</div><p class="tiny muted" style="margin-top:20px">Las claves de pagos y correo se configuran en el archivo privado del servidor. No se muestran en el navegador.</p></section><section class="panel"><h2>Productos con stock bajo</h2>${d.low_stock.slice(0,8).map(p=>`<div class="between" style="padding:10px 0;border-bottom:1px solid #29313e"><span class="tiny">${esc(p.name)}</span><strong>${p.stock}</strong></div>`).join('')||'<p>Todos los productos tienen más de 5 unidades.</p>'}<p style="margin-top:18px"><a class="accent" href="#admin?tab=productos">Gestionar inventario →</a></p></section></div>`}else if(tab==='productos'){state.adminProducts=await api('admin-products');body=`<div class="admin-toolbar"><input id="admin-product-search" placeholder="Buscar nombre, SKU o categoría…" aria-label="Buscar productos de administración"><button class="button" data-edit-product="0">${icon('plus')}Nuevo producto</button></div><div class="panel table-scroll"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Venta</th><th></th></tr></thead><tbody id="admin-product-rows">${adminProductRows(state.adminProducts)}</tbody></table></div>`}else if(tab==='pedidos'){state.adminOrders=await api('admin-orders');body=`<div class="admin-toolbar"><p>${state.adminOrders.length} pedidos recientes</p><a class="button secondary" href="/api.php?action=admin-export">Exportar CSV</a></div><div class="panel table-scroll"><table><thead><tr><th>Pedido / Cliente</th><th>Total</th><th>Método</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${state.adminOrders.map(o=>`<tr><td><strong>${esc(o.id)}</strong><br><small>${esc(o.customer)} · ${esc(o.email)}</small><br><small class="muted">${date(o.created_at)}</small></td><td>${money(o.total)}</td><td>${esc(o.provider)}</td><td>${statusBadge(o.status)}</td><td><button data-admin-order="${o.id}">Ver / gestionar</button></td></tr>`).join('')||'<tr><td colspan="5">Aún no hay pedidos.</td></tr>'}</tbody></table></div>`}else if(tab==='clientes'){const customers=await api('admin-customers');body=`<div class="panel table-scroll"><table><thead><tr><th>Cliente</th><th>Correo</th><th>Teléfono</th><th>Pedidos</th><th>Alta</th></tr></thead><tbody>${customers.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.phone||'—')}</td><td>${u.order_count}</td><td>${date(u.created_at)}</td></tr>`).join('')||'<tr><td colspan="5">Todavía no hay clientes.</td></tr>'}</tbody></table></div>`}else if(tab==='actividad'){const events=await api('admin-audit');body=`<div class="panel table-scroll"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Detalle</th></tr></thead><tbody>${events.map(x=>`<tr><td>${date(x.created_at)}</td><td>${esc(x.name)}</td><td>${esc(x.action)}</td><td><small>${esc(x.detail)}</small></td></tr>`).join('')}</tbody></table></div>`}else{const d=await api('admin-dashboard');const s=d.settings;body=`<form id="settings-form" class="stack"><section class="panel"><h2>Datos de la tienda</h2><div class="form-grid">${[['store_name','Nombre de tienda',s.store_name],['support_email','Correo de atención',s.support_email],['support_phone','Teléfono de atención',s.support_phone],['legal_name','Nombre o razón social',s.legal_name],['legal_address','Domicilio del negocio',s.legal_address]].map(([n,l,v])=>`<label>${l}<input name="${n}" value="${esc(v)}" ${n==='support_email'?'type="email"':''}></label>`).join('')}</div></section><section class="panel"><h2>Envíos y transferencias</h2><div class="form-grid"><label>Costo de envío (MXN)<input name="shipping_price" type="number" step="0.01" min="0" value="${s.shipping_price/100}" required></label><label>Envío gratis desde (MXN)<input name="free_shipping" type="number" step="0.01" min="0" value="${s.free_shipping/100}" required></label><label class="full">Instrucciones de transferencia (banco, titular y CLABE)<textarea name="bank_instructions" maxlength="2000">${esc(s.bank_instructions)}</textarea></label></div><p class="tiny muted">Mercado Pago, Stripe y SMTP se configuran en private/config.php. Las opciones de efectivo y billeteras dependen de los métodos habilitados en tus cuentas.</p></section><section class="panel stack"><h2>Políticas de la tienda</h2>${[['privacy_text','Aviso de privacidad'],['terms_text','Términos y condiciones'],['returns_text','Cambios, devoluciones y garantías']].map(([n,l])=>`<label>${l}<textarea name="${n}" maxlength="15000" rows="7">${esc(s[n])}</textarea></label>`).join('')}</section><section class="panel stack"><h2>Activación de ventas</h2><label class="check-label"><input type="checkbox" name="demo_mode" ${s.demo_mode?'checked':''}><span>Mantener el modo de demostración (sin cobros reales)</span></label><p class="tiny muted">Antes de desactivar la demostración, configura los datos comerciales, políticas y al menos un método de pago. En cada producto confirma el precio y las existencias y marca “Verificado para venta”.</p><button type="submit" class="button">Guardar configuración</button></section></form>`}return `<div class="wrap page">${breadcrumb('Administración')}<div class="page-title"><span class="eyebrow">NEXTECH ADMIN</span><h1>Tu tienda, bajo control.</h1></div><nav class="admin-tabs" aria-label="Administración">${[['resumen','Resumen'],['productos','Productos'],['pedidos','Pedidos'],['clientes','Clientes'],['configuracion','Configuración'],['actividad','Actividad']].map(([v,t])=>`<a href="#admin?tab=${v}" class="${tab===v?'active':''}">${t}</a>`).join('')}</nav>${body}</div>`}
function adminProductRows(items){return items.map(p=>`<tr><td><div class="flex">${photo(p)}<div><strong>${esc(p.name)}</strong><br><small class="muted">${esc(p.sku)}</small></div></div></td><td>${esc(catName(p.category))}</td><td>${money(p.price)}</td><td>${p.stock}</td><td><small>${!p.active?'Oculto':p.verified?'Verificado':'Por verificar'}</small></td><td><button data-edit-product="${p.id}">Editar</button></td></tr>`).join('')}
function editProduct(id){const p=state.adminProducts?.find(x=>x.id===id)||{id:0,sku:'',category:'accesorios',name:'',brand:'',description:'',specs:{},image:'',source_url:'',price:0,compare_price:0,stock:0,active:1,featured:0,verified:0};modal(p.id?'Editar producto':'Nuevo producto',`<form id="product-form" class="form-grid"><input type="hidden" name="id" value="${p.id}"><label class="full">Nombre<input name="name" value="${esc(p.name)}" required maxlength="220"></label><label>SKU<input name="sku" value="${esc(p.sku)}" required maxlength="80"></label><label>Marca<input name="brand" value="${esc(p.brand)}" required maxlength="90"></label><label class="full">Categoría<select name="category">${state.categories.map(c=>`<option value="${c.slug}" ${c.slug===p.category?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="full">Descripción<textarea name="description" required maxlength="10000">${esc(p.description)}</textarea></label><label>Precio MXN<input name="price" type="number" step="0.01" min="0" value="${p.price/100}" required></label><label>Precio anterior MXN (0 si no aplica)<input name="compare_price" type="number" step="0.01" min="0" value="${p.compare_price/100}" required></label><label>Existencias<input name="stock" type="number" min="0" step="1" value="${p.stock}" required></label><label>Subir imagen<input id="product-upload" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="full">Imagen (ruta local o URL HTTPS)<input name="image" id="product-image-url" value="${esc(p.image)}"></label><label class="full">Fuente del fabricante<input name="source_url" type="url" value="${esc(p.source_url)}"></label><label class="full">Especificaciones (una por línea: nombre: valor)<textarea name="specs" rows="6">${esc(Object.entries(p.specs).map(([k,v])=>k+': '+v).join('\n'))}</textarea></label>${[['active','Visible en el catálogo'],['featured','Destacado en la portada'],['verified','Precio, stock y datos verificados para venta real']].map(([n,l])=>`<label class="check-label full"><input name="${n}" type="checkbox" ${p[n]?'checked':''}>${l}</label>`).join('')}<button class="button full" type="submit">Guardar producto</button></form>`)}
function manageOrder(id){const o=state.adminOrders.find(x=>x.id===id);if(!o)return;const a=o.address;const options=({pending:['paid','cancelled'],paid:['processing'],processing:['shipped'],shipped:['delivered']})[o.status]||[];const allowed=o.status==='pending'&&!['demo','transfer'].includes(o.provider)?[]:options;modal('Pedido '+o.id,`<div class="stack">${statusBadge(o.status)}<p>${esc(o.customer)} · ${esc(o.email)}<br>${esc(a.recipient)} · ${esc(a.phone)}<br>${esc(a.street)}, ${esc(a.colony)}, ${esc(a.city)}, ${esc(a.state)} CP ${esc(a.postal_code)}<br>${esc(a.notes||'')}</p><div>${o.items.map(p=>`<div class="between tiny"><span>${p.qty} × ${esc(p.name)}</span><strong>${money(p.price*p.qty)}</strong></div>`).join('')}</div><strong>Total: ${money(o.total)} · ${esc(o.provider)}</strong><p class="tiny muted">${esc(o.notes)}</p>${allowed.length?`<form id="admin-order-form" class="stack"><input type="hidden" name="id" value="${o.id}"><label>Actualizar estado<select name="status">${allowed.map(s=>`<option value="${s}">${statusLabels[s]}</option>`).join('')}</select></label><label>Paquetería y número de guía<input name="tracking" value="${esc(o.tracking)}" maxlength="200"></label>${o.status==='pending'?'<label class="check-label"><input type="checkbox" required>Confirmo que revisé el pago o la cancelación de este pedido.</label>':''}<button class="button" type="submit">Aplicar cambio</button></form>`:'<p class="notice">No hay cambios manuales disponibles. Los pagos de pasarela se confirman mediante sus notificaciones verificadas.</p>'}<ul class="timeline">${o.events.map(e=>`<li>${esc(e.message)}<small>${date(e.created_at)}</small></li>`).join('')}</ul></div>`)}
async function otherPage(path,params){if(path==='cuenta')return accountPage(params);if(path==='checkout')return checkoutPage();if(path==='pedido')return orderPage(params);if(path==='admin')return adminPage(params);if(['privacidad','terminos','devoluciones'].includes(path))return policyPage(path);if(path==='ayuda')return helpPage();if(path==='restablecer')return `<div class="wrap page"><section class="panel auth-panel"><h1>Una nueva contraseña</h1><form id="reset-form" class="stack"><input type="hidden" name="token" value="${esc(params.get('token')||'')}"><label>Nueva contraseña<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><button class="button" type="submit">Guardar nueva contraseña</button></form></section></div>`;return `<div class="wrap page">${empty('No encontramos esa página','Puedes seguir explorando el catálogo.','#inicio','Volver al inicio')}</div>`}
async function extraClick(e){const el=e.target.closest('[data-auth-mode],[data-forgot],[data-logout],[data-address],[data-delete-address],[data-edit-product],[data-admin-order],[data-cancel-order],[data-confirm-cancel],[data-confirm-address-delete],[data-retry-payment],[data-refresh]');if(!el)return;e.preventDefault();try{if(el.dataset.authMode){shell(authForm(el.dataset.authMode));return}if(el.hasAttribute('data-forgot')){modal('Recupera tu cuenta','<form id="forgot-form" class="stack"><p>Te enviaremos un enlace para restablecer tu contraseña.</p><label>Correo electrónico<input name="email" type="email" required autocomplete="email"></label><button class="button" type="submit">Enviar enlace</button></form>');return}if(el.hasAttribute('data-logout')){await api('logout',{});state.user=null;state.favorites=[];Object.assign(state,await api('bootstrap'));await loadCart();location.hash='inicio';await route();return}if(el.hasAttribute('data-address')){const a=state.addresses?.find(x=>Number(x.id)===Number(el.dataset.address))||{};modal(a.id?'Editar dirección':'Nueva dirección',addressForm(a));return}if(el.dataset.deleteAddress){modal('Eliminar dirección',`<p>Esta dirección dejará de estar disponible para próximas compras. Los pedidos anteriores conservarán sus datos de entrega.</p><button class="button" data-confirm-address-delete="${Number(el.dataset.deleteAddress)}">Eliminar dirección</button>`);return}if(el.dataset.confirmAddressDelete){await api('address-delete',{id:Number(el.dataset.confirmAddressDelete)});$('#modal').close();toast('Dirección eliminada');await route();return}if(el.hasAttribute('data-edit-product')){editProduct(Number(el.dataset.editProduct));return}if(el.dataset.adminOrder){manageOrder(el.dataset.adminOrder);return}if(el.dataset.cancelOrder){modal('Cancelar pedido',`<p>El pedido se cancelará y sus unidades volverán al inventario. Si ya hiciste una transferencia, contacta a la tienda antes de cancelar.</p><button class="button" data-confirm-cancel="${esc(el.dataset.cancelOrder)}">Confirmar cancelación</button>`);return}if(el.dataset.confirmCancel){await api('cancel-order',{id:el.dataset.confirmCancel});$('#modal').close();toast('Pedido cancelado');await route();return}if(el.dataset.retryPayment){el.disabled=true;try{const r=await api('retry-payment',{id:el.dataset.retryPayment});location.assign(r.url)}finally{el.disabled=false}return}if(el.hasAttribute('data-refresh'))await route()}catch(error){toast(error.message)}}
async function extraChange(e){if(e.target.id==='checkout-address'){const a=state.addresses.find(x=>Number(x.id)===Number(e.target.value));if(a){for(const [k,v]of Object.entries(a)){const el=$(`[name="${k}"]`,$('#checkout-form'));if(el&&el.type!=='radio')el.value=v}}}if(e.target.id==='product-upload'){const f=e.target.files[0];if(!f)return;const data=new FormData;data.append('image',f);try{const r=await api('upload',data);$('#product-image-url').value=r.url;toast('Imagen subida')}catch(error){toast(error.message)}}}
document.addEventListener('input',e=>{if(e.target.id==='admin-product-search'){const q=e.target.value.toLocaleLowerCase();$('#admin-product-rows').innerHTML=adminProductRows(state.adminProducts.filter(p=>(p.name+' '+p.sku+' '+p.brand+' '+p.description+' '+catName(p.category)).toLocaleLowerCase().includes(q)));imageFallbacks()}});
async function extraSubmit(e){const form=e.target;const d=Object.fromEntries(new FormData(form));await busy(form,async()=>{switch(form.id){case 'auth-form':{const r=await api(form.dataset.mode,{...d,accept:!!d.accept});Object.assign(state,r);await mergeCart();state.favorites=(await api('favorites')).map(p=>p.id);const next=sessionStorage.getItem('nextech_return')||'cuenta';sessionStorage.removeItem('nextech_return');location.hash=next;await route();toast('Bienvenido a NexTech');break}case 'profile-form':Object.assign(state,await api('profile',d));toast('Perfil actualizado');await route();break;case 'password-form':Object.assign(state,await api('password',d));form.reset();toast('Contraseña actualizada');break;case 'forgot-form':{const r=await api('forgot',d);$('#modal').close();toast(r.message);break}case 'reset-form':await api('reset',d);Object.assign(state,await api('bootstrap'));location.hash='cuenta';await route();toast('Contraseña guardada. Inicia sesión de nuevo.');break;case 'address-form':await api('address',d);$('#modal').close();toast('Dirección guardada');await route();break;case 'checkout-form':{const address={...d};delete address.provider;delete address.accept;const o=await api('checkout',{provider:d.provider,address,accept:!!d.accept,key:state.checkoutKey});state.checkoutKey=null;await loadCart();location.hash='pedido?id='+o.id;await route();toast('Pedido creado');break}case 'product-form':{const specs={};for(const line of d.specs.split('\n').filter(x=>x.trim())){const i=line.indexOf(':');if(i<1)throw Error('Cada especificación debe tener nombre: valor.');specs[line.slice(0,i).trim()]=line.slice(i+1).trim()}await api('admin-product',{...d,id:Number(d.id),price:Math.round(Number(d.price)*100),compare_price:Math.round(Number(d.compare_price)*100),stock:Number(d.stock),active:!!d.active,featured:!!d.featured,verified:!!d.verified,specs});$('#modal').close();toast('Producto guardado');await route();break}case 'admin-order-form':await api('admin-order',d);$('#modal').close();toast('Pedido actualizado');await route();break;case 'settings-form':await api('admin-settings',{...d,demo_mode:!!d.demo_mode,shipping_price:Math.round(Number(d.shipping_price)*100),free_shipping:Math.round(Number(d.free_shipping)*100)});Object.assign(state,await api('bootstrap'));toast('Configuración guardada');await route();break}})}
bootstrap();
